#include "../src/music_library.hpp"
#include "../src/music_art.hpp"
#include <cassert>
#include <filesystem>
#include <iostream>
int main(){using namespace day;MusicLibrary lib;auto id=lib.create("Новый плейлист");assert(!id.empty());assert(lib.add(id,"x/b.mp3")&&lib.add(id,"x/a.mp3"));assert(!lib.add(id,"x/a.mp3"));std::vector<std::string> files={"x/a.mp3","x/b.mp3","x/c.mp3"};assert(lib.rows(files,id)==std::vector<int>({1,0}));lib.move(id,"x/a.mp3",-1);assert(lib.rows(files,id)==std::vector<int>({0,1}));lib.find(id)->title="Renamed";std::filesystem::create_directories("work/library-test");std::string path="work/library-test/playlists.json";assert(lib.save(path));lib.add("list:favourites","x/c.mp3");assert(lib.save(path));MusicLibrary restored;restored.load(path);assert(restored.find(id)->title=="Renamed"&&restored.has("list:favourites","x/c.mp3"));std::ofstream(path+".0")<<"broken snapshot";restored.load(path);assert(restored.find(id)->title=="Renamed"&&!restored.has("list:favourites","x/c.mp3"));lib.remove(id,"x/a.mp3");assert(lib.rows(files,id)==std::vector<int>({1}));lib.forget("x/b.mp3");assert(lib.rows(files,id).empty());lib.erase(id);assert(!lib.find(id));lib.erase("list:favourites");assert(lib.find("list:favourites"));assert(lib.create("").empty());
std::vector<unsigned char> picture={3,'i','m','a','g','e','/','p','n','g',0,3,0,137,'P','N','G',13,10,26,10};std::vector<unsigned char> frame={'A','P','I','C',0,0,0,(unsigned char)picture.size(),0,0};frame.insert(frame.end(),picture.begin(),picture.end());auto art=parseMusicArtwork(frame,3,0);assert(art.png&&art.type==3&&art.bytes.size()==8);frame.pop_back();assert(parseMusicArtwork(frame,3,0).bytes.empty());std::filesystem::remove_all("work/library-test");std::cout<<"Custom playlist order, deduplication, favorites, rename/remove, persisted snapshots and corrupt-snapshot recovery; ID3 cover extraction/truncation: PASS\n";}
